from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            area = (r1-r0+1)*(c1-c0+1)
            # A mostly filled rectangular 3-object, allowing holes replaced by marker 2s.
            if len(cells) / area >= 0.65:
                boxes.append((r0, r1, c0, c1))
    targets = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if any(r0 <= r <= r1 and c0 <= c <= c1 for r0, r1, c0, c1 in boxes):
                targets.add((r, c))
    out = [row[:] for row in grid]
    for r, c in targets:
        for y in range(max(0, r-1), min(h, r+2)):
            for x in range(max(0, c-1), min(w, c+2)):
                if grid[y][x] != 2:
                    out[y][x] = 1
    return out
